({ reorderCheck(input) {
  const allowed = ["averageDailySales", "leadTimeDays", "stockOnHand"];
  for (const name of Object.keys(input)) {
    if (!allowed.includes(name)) {
      throw new Error("unknown field: " + name);
    }
  }
  const leadTimeDemand = input.averageDailySales * input.leadTimeDays;
  const safetyStock = 0.2 * leadTimeDemand;
  const reorderPoint = leadTimeDemand + safetyStock;
  const reorder = input.stockOnHand <= reorderPoint;
  return { leadTimeDemand, safetyStock, reorderPoint, reorder };
} })

