build.unitScript:
test("sales 50 a day with 6 day lead time gives lead-time demand 300, safety stock 60, reorder point 360", () => {
  const r = code.reorderCheck({ averageDailySales: 50, leadTimeDays: 6, stockOnHand: 360 });
  assert.equal(r.leadTimeDemand, 300);
  assert.equal(r.safetyStock, 60);
  assert.equal(r.reorderPoint, 360);
});
test("stock exactly at the reorder point of 360 recommends a reorder", () => {
  assert.deepEqual(code.reorderCheck({ averageDailySales: 50, leadTimeDays: 6, stockOnHand: 360 }), { leadTimeDemand: 300, safetyStock: 60, reorderPoint: 360, reorder: true });
});
test("stock of 361, one above the reorder point of 360, does not recommend a reorder", () => {
  assert.equal(code.reorderCheck({ averageDailySales: 50, leadTimeDays: 6, stockOnHand: 361 }).reorder, false);
});
test("stock well below the reorder point recommends a reorder", () => {
  assert.equal(code.reorderCheck({ averageDailySales: 50, leadTimeDays: 6, stockOnHand: 100 }).reorder, true);
});
test("sales 10 a day with 5 day lead time gives reorder point 60 and stock 61 does not reorder", () => {
  assert.deepEqual(code.reorderCheck({ averageDailySales: 10, leadTimeDays: 5, stockOnHand: 61 }), { leadTimeDemand: 50, safetyStock: 10, reorderPoint: 60, reorder: false });
});
test("an input field outside the contract is rejected with unknown field error", () => {
  assert.throws(() => code.reorderCheck({ averageDailySales: 50, leadTimeDays: 6, stockOnHand: 360, price: 2 }), /unknown field: price/);
});

build.testScript:
test("lead-time demand is average daily sales times lead time in days", function() {
  var result = code.reorderCheck({ averageDailySales: 50, leadTimeDays: 6, stockOnHand: 360 });
  assert.equal(result.leadTimeDemand, 300);
});
test("safety stock is 20 percent of lead-time demand", function() {
  var result = code.reorderCheck({ averageDailySales: 50, leadTimeDays: 6, stockOnHand: 360 });
  assert.equal(result.leadTimeDemand, 300);
  assert.equal(result.safetyStock, 60);
});
test("reorder point is lead-time demand plus safety stock and equals 1.2 times lead-time demand", function() {
  var result = code.reorderCheck({ averageDailySales: 50, leadTimeDays: 6, stockOnHand: 360 });
  assert.equal(result.leadTimeDemand, 300);
  assert.equal(result.safetyStock, 60);
  assert.equal(result.reorderPoint, result.leadTimeDemand + result.safetyStock);
  assert.equal(result.reorderPoint, 1.2 * result.leadTimeDemand);
  assert.equal(result.reorderPoint, 360);
});
test("example with daily sales of 50 and a lead time of 6 days gives lead-time demand 300, safety stock 60 and reorder point 360", function() {
  var result = code.reorderCheck({ averageDailySales: 50, leadTimeDays: 6, stockOnHand: 360 });
  assert.deepEqual(result, { leadTimeDemand: 300, safetyStock: 60, reorderPoint: 360, reorder: true });
});
test("recommends a reorder when stock on hand is at the reorder point", function() {
  var result = code.reorderCheck({ averageDailySales: 50, leadTimeDays: 6, stockOnHand: 360 });
  assert.equal(result.reorderPoint, 360);
  assert.equal(result.reorder, true);
});
test("does not recommend a reorder when stock on hand is above the reorder point", function() {
  var result = code.reorderCheck({ averageDailySales: 50, leadTimeDays: 6, stockOnHand: 361 });
  assert.equal(result.reorderPoint, 360);
  assert.equal(result.reorder, false);
});

